import type { Mark } from "@docshunt/docs-editor-wasm";

/**
 * Mark union에서 표시용 문자열을 추출합니다.
 * - `string` → 그대로 반환 (레거시 호환)
 * - `{ char }` 형태 → char 반환
 * - `{ format, suffix? }` 형태 → suffix 반환 (없으면 빈 문자열)
 * - `null | undefined` → 빈 문자열
 */
export function extractMarkText(mark: Mark | string | null | undefined): string {
  if (mark == null) return "";
  if (typeof mark === "string") return mark;
  return "char" in mark ? mark.char : (mark.suffix ?? "");
}
